import{_ as n,o as e,c as o,a5 as i}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Team Guide — Quy trình phát triển tính năng BrandHub","description":"","frontmatter":{},"headers":[],"relativePath":"team_guide.md","filePath":"team_guide.md"}'),a={name:"team_guide.md"};function c(r,t,h,s,d,g){return e(),o("div",null,[...t[0]||(t[0]=[i(`<h1 id="team-guide-—-quy-trinh-phat-trien-tinh-nang-brandhub" tabindex="-1">Team Guide — Quy trình phát triển tính năng BrandHub <a class="header-anchor" href="#team-guide-—-quy-trinh-phat-trien-tinh-nang-brandhub" aria-label="Permalink to &quot;Team Guide — Quy trình phát triển tính năng BrandHub&quot;">​</a></h1><p>&gt; Hướng dẫn chuẩn cho toàn bộ thành viên khi nhận và hoàn thành một task Jira. &gt; Đọc kỹ trước khi bắt đầu. Mọi bước có tài liệu gốc tham chiếu đều ghi rõ đường dẫn.</p><hr><h2 id="_1-boi-canh" tabindex="-1">1. Bối cảnh <a class="header-anchor" href="#_1-boi-canh" aria-label="Permalink to &quot;1. Bối cảnh&quot;">​</a></h2><ul><li>Các task mới đã được thêm lên Jira. Công việc <strong>phụ thuộc lẫn nhau nhiều</strong> và sprint 8 đã gần hết, nên nếu có chồng chéo thì phần chưa làm được chuyển sang sprint sau.</li><li>Vì thời gian gấp và việc cấn nhau, <strong>phân task trên Jira chỉ là một phần</strong> — ai thấy task nào có thể làm trước thì chủ động làm để đẩy nhanh tiến độ.</li><li><strong>Trước khi bắt đầu:</strong> pull code mới nhất của <code>develop</code> (cả <code>brandhub-infrastructure</code> và <code>brandhub-business-service</code>).</li></ul><hr><h2 id="_2-quy-trinh-8-buoc" tabindex="-1">2. Quy trình 8 bước <a class="header-anchor" href="#_2-quy-trinh-8-buoc" aria-label="Permalink to &quot;2. Quy trình 8 bước&quot;">​</a></h2><h3 id="buoc-1-—-nhan-task-tren-jira" tabindex="-1">Bước 1 — Nhận task trên Jira <a class="header-anchor" href="#buoc-1-—-nhan-task-tren-jira" aria-label="Permalink to &quot;Bước 1 — Nhận task trên Jira&quot;">​</a></h3><p>Mở Jira, xem task được giao, ghi nhớ mã task (ví dụ <code>DA-47</code>), kéo task sang <strong>In Progress</strong>.</p><p><strong>Nếu công việc phát sinh chưa có task trên Jira</strong> (ví dụ phát hiện qua audit/review, hoặc bug ngoài scope task đang làm):</p><ol><li>Tạo task Jira mới (Task hoặc Bug tùy loại), đặt tên theo đúng pattern <code>[DA-Exx-yy] &lt;Mô tả&gt;</code> — số <code>yy</code> nối tiếp task cuối cùng của epic đó (không trùng số).</li><li><strong>Gán vào đúng Epic</strong> (field <code>parent</code>) và <strong>gán đúng Sprint hiện tại đang active</strong> (field Sprint) — không để task mồ côi không epic/không sprint.</li><li>Ghi rõ trong description: <code>Ghi chú: Không có trong plan gốc — phát sinh từ &lt;lý do&gt;. Docs: &lt;đường dẫn liên quan&gt;.</code></li><li>Bổ sung ngay task đó vào <code>brandhub-master-plan.md</code> — thêm dòng vào bảng Epic tương ứng + mục chi tiết theo mẫu các task <code>_(phát sinh, ngoài plan gốc)_</code> đã có sẵn (xem EPIC E12 làm ví dụ).</li></ol><h3 id="buoc-2-—-lam-tai-lieu-report-3-srs-va-report-4-sdd" tabindex="-1">Bước 2 — Làm tài liệu Report 3 (SRS) và Report 4 (SDD) <a class="header-anchor" href="#buoc-2-—-lam-tai-lieu-report-3-srs-va-report-4-sdd" aria-label="Permalink to &quot;Bước 2 — Làm tài liệu Report 3 (SRS) và Report 4 (SDD)&quot;">​</a></h3><p>Mỗi task/FR cần cập nhật <strong>2 tài liệu report</strong>:</p><ul><li><strong>Report 3 — SRS</strong> (<code>FormReportDA/reports/BrandHub_Report3_Software_Requirement_Specification.docx</code>): viết <strong>spec cho FR</strong> theo mẫu chuẩn (xem <a href="#3-mẫu-spec-fr-cho-report-3-srs">§3</a>). Screenshot FE sẽ chèn sau khi code xong ở Bước 7.</li><li><strong>Report 4 — SDD</strong> (<code>FormReportDA/reports/BrandHub_Report4_Software_Design_Document.docx</code>): vẽ <strong>Sequence diagram</strong> cho FR.</li></ul><p>Report 1 và Report 2 đã được hoàn thiện (Trung + Phước phụ trách), thành viên <strong>không cần động vào</strong>:</p><ul><li><code>FormReportDA/reports/BrandHub_Report1_Project_Introduction.docx</code></li><li><code>FormReportDA/reports/BrandHub_Report2_Project_Management_Plan.docx</code></li></ul><h3 id="buoc-3-—-đoc-tai-lieu-nghiep-vu-spec-ba" tabindex="-1">Bước 3 — Đọc tài liệu nghiệp vụ (spec + BA) <a class="header-anchor" href="#buoc-3-—-đoc-tai-lieu-nghiep-vu-spec-ba" aria-label="Permalink to &quot;Bước 3 — Đọc tài liệu nghiệp vụ (spec + BA)&quot;">​</a></h3><ol><li>Vào <code>brandhub-infrastructure/docs/feature/&lt;tên-feature&gt;/</code>.</li><li>Đọc file <code>spec.md</code> (đặc tả ban đầu của feature). File này có liên kết tới thư mục phân tích nghiệp vụ <code>brandhub-infrastructure/docs/ba/</code> — <strong>đọc qua toàn bộ phần BA liên quan trước</strong>.</li><li>Nếu phát hiện spec/BA <strong>sai hoặc thiếu</strong> → chỉnh lại spec cho đúng, hoặc làm chi tiết hơn nếu cần.</li></ol><h3 id="buoc-4-—-viet-3-tai-lieu-con-lai-theo-mau" tabindex="-1">Bước 4 — Viết 3 tài liệu còn lại theo mẫu <a class="header-anchor" href="#buoc-4-—-viet-3-tai-lieu-con-lai-theo-mau" aria-label="Permalink to &quot;Bước 4 — Viết 3 tài liệu còn lại theo mẫu&quot;">​</a></h3><p>Mẫu đặt tại <code>brandhub-infrastructure/docs/feature/system-maintenance/definition/</code>. Mỗi feature phải có đủ 4 file:</p><table tabindex="0"><thead><tr><th>File</th><th>Vai trò</th><th>Trả lời câu hỏi</th></tr></thead><tbody><tr><td><code>spec.md</code></td><td>Đặc tả nghiệp vụ (đã có ở Bước 3)</td><td><strong>Làm gì, cho ai, đúng ra sao</strong></td></tr><tr><td><code>plan.md</code></td><td>Kế hoạch triển khai kỹ thuật</td><td><strong>Làm thế nào</strong></td></tr><tr><td><code>task.md</code></td><td>Checklist phân rã công việc</td><td><strong>Làm từng bước gì, xong chưa</strong></td></tr><tr><td><code>test.md</code></td><td>Kịch bản test case</td><td><strong>Kiểm tra gì để biết đúng</strong></td></tr></tbody></table><ul><li>Tuân thủ đúng thứ tự <code>spec → plan → task → test</code> trước khi viết code.</li><li>Thư mục feature đặt theo <strong>kebab-case tiếng Anh</strong> (ví dụ <code>multi-method-login</code>).</li><li>Quy tắc viết và ranh giới giữa 4 file xem tại <code>brandhub-infrastructure/docs/rule/feature-workflow.md</code>.</li></ul><p><strong>Quy định bắt buộc — kể cả khi SỬA code đã có (không chỉ code mới):</strong></p><p>Mọi thay đổi vào logic nghiệp vụ (business rule, luồng xử lý, validation, error code) đều phải đi tuần tự đúng chuỗi tài liệu, không được nhảy thẳng vào code:</p><ol><li><strong><code>spec.md</code></strong> — trước tiên đối chiếu với BA (<code>brandhub-infrastructure/docs/ba/</code>). Đây là tài liệu <strong>quan trọng dùng chung toàn team</strong> — nếu code/thực tế đang làm khác với những gì <code>spec.md</code> (và BA gốc) mô tả, <strong>không được tự ý sửa spec cho khớp code một mình</strong>. Phải báo lên kênh chung của team để cả team chốt lại đâu là đúng (BA sai cần cập nhật, hay code đang làm sai cần sửa lại) — vì đây là nguồn tham chiếu chung, một người tự sửa lệch sẽ làm sai luôn cả những phần khác đang dựa vào nó.</li><li><strong><code>plan.md</code></strong> — chỉ viết plan sau khi <code>spec.md</code> đã chốt đúng. Không viết plan dựa trên spec còn đang tranh cãi.</li><li><strong><code>task.md</code></strong> — phân rã từ <code>plan.md</code> đã chốt, không tự thêm việc ngoài plan.</li><li><strong><code>test.md</code></strong> — viết test case dựa trên <code>spec.md</code> + <code>task.md</code>, phủ đủ happy/unhappy case, trước khi hoặc song song với code — không viết test sau khi code xong để &quot;test cho khớp code&quot;.</li><li><strong>Code</strong> — implement đúng theo 4 file trên. Nếu trong lúc code phát hiện spec/plan sai → dừng lại, quay về bước 1, không tự sửa code lệch tài liệu rồi để tài liệu cũ nằm im.</li></ol><p>Áp dụng cho <strong>cả 34 FR hiện có lẫn feature mới</strong> — sửa một FR đang chạy production cũng phải đi lại đúng chuỗi này, không được sửa thẳng code production rồi cập nhật tài liệu sau (hoặc quên cập nhật).</p><h3 id="buoc-5-—-viet-code-theo-đung-tai-lieu-tach-be-fe" tabindex="-1">Bước 5 — Viết code theo đúng tài liệu (tách BE / FE) <a class="header-anchor" href="#buoc-5-—-viet-code-theo-đung-tai-lieu-tach-be-fe" aria-label="Permalink to &quot;Bước 5 — Viết code theo đúng tài liệu (tách BE / FE)&quot;">​</a></h3><p>Code đúng theo tài liệu đã viết ở Bước 3–4, không tự suy diễn nghiệp vụ ngoài spec. Test bắt buộc phủ đủ <strong>happy case</strong> và <strong>unhappy case</strong> (edge case, error case).</p><p><strong>Backend (<code>brandhub-business-service</code>)</strong>:</p><ul><li>Entity, controller, service interface đã triển khai sẵn → chỉ cần <strong>implement service impl</strong>.</li><li>Viết test cho phần logic nghiệp vụ.</li><li><strong>Bắt buộc tuân thủ</strong> <code>brandhub-business-service/rule.md</code> — package structure, API response format (<code>ApiResponse&lt;T&gt;</code>), ErrorCode enum, JPA/transaction convention, JWT/BCrypt security, clean code (method ≤30 dòng, ≤3 params, không magic number/string), test coverage (≥80% service layer). Checklist đầy đủ ở §13 file đó — chạy qua trước khi mở PR.</li></ul><p><strong>Frontend (<code>brandhub-web-dashboard</code> / <code>brandhub-mobile-app</code>)</strong>:</p><ul><li>Code UI theo spec, đảm bảo <strong>responsive</strong> trên các kích thước màn hình.</li><li><strong>Bắt buộc tuân thủ</strong> <code>brandhub-web-dashboard/rule.md</code> — theme light/dark (token semantic, không hardcode hex), i18n (<code>t()</code>, key song song vi/en), component dùng chung (Button/Input/ Spinner, không tự chế), TypeScript nghiêm ngặt (không <code>any</code>), kiến trúc feature-based (<code>pages/[feature]/components/</code>, orchestrator &lt;150 dòng), clean code (hàm ≤30 dòng, file ≤300 dòng). Checklist đầy đủ ở §12 file đó — chạy qua trước khi mở PR.</li></ul><p>&gt; Làm cẩn thận, check kỹ. Không làm ẩu bằng AI — sửa lại tốn công hơn nhiều.</p><h3 id="buoc-6-—-commit-theo-chuan" tabindex="-1">Bước 6 — Commit theo chuẩn <a class="header-anchor" href="#buoc-6-—-commit-theo-chuan" aria-label="Permalink to &quot;Bước 6 — Commit theo chuẩn&quot;">​</a></h3><p>Commit đúng theo <code>brandhub-infrastructure/docs/rule/git-commit-convention.md</code>.</p><ul><li><strong>Không cần</strong> đặt tên nhánh trùng mã Jira.</li><li><strong>Điều quan trọng:</strong> message commit phải chứa đúng mã task Jira, ví dụ <code>feat(DA-47): ...</code>.</li></ul><h3 id="buoc-7-—-đong-task-tren-jira" tabindex="-1">Bước 7 — Đóng task trên Jira <a class="header-anchor" href="#buoc-7-—-đong-task-tren-jira" aria-label="Permalink to &quot;Bước 7 — Đóng task trên Jira&quot;">​</a></h3><ol><li>Kéo task <strong>In Progress → In Review</strong>, chờ lead/người duyệt.</li><li>Sau khi được duyệt → kéo sang <strong>Done</strong>.</li><li>Chụp màn hình <strong>FE của màn hình đó</strong>, chèn vào <strong>Report 3 (SRS)</strong>.</li></ol><h3 id="buoc-8-—-cap-nhat-trang-thai-fr-tren-excel" tabindex="-1">Bước 8 — Cập nhật trạng thái FR trên Excel <a class="header-anchor" href="#buoc-8-—-cap-nhat-trang-thai-fr-tren-excel" aria-label="Permalink to &quot;Bước 8 — Cập nhật trạng thái FR trên Excel&quot;">​</a></h3><p>Cập nhật cột <strong><code>Hiện trạng</code></strong> trong file <code>brandhub-infrastructure/docs/Các FR của hệ thống - Feature_Function Requirement.csv</code> để cả team nắm được tiến độ.</p><hr><h2 id="_3-mau-spec-fr-cho-report-3-srs" tabindex="-1">3. Mẫu spec FR cho Report 3 (SRS) <a class="header-anchor" href="#_3-mau-spec-fr-cho-report-3-srs" aria-label="Permalink to &quot;3. Mẫu spec FR cho Report 3 (SRS)&quot;">​</a></h2><p>&gt; Trích từ <code>FormReportDA/report_drafts/DA-763_R3_S3.2.1_FR_Register_Email.md</code>. &gt; Thay <code>DA-xxx</code>, <code>§x.y.z</code>, tên FR và nội dung cho khớp task của mình.</p><h3 id="header" tabindex="-1">Header <a class="header-anchor" href="#header" aria-label="Permalink to &quot;Header&quot;">​</a></h3><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># DA-xxx — [&lt;mã cha&gt;] [R3 §x.y.z] Write FR — &lt;Tên FR&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">&gt; Report: Report 3 — SRS | Section: §x.y.z | Assignee: &lt;tên&gt;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">&gt; Source: &lt;Controller.java&gt;, &lt;ServiceImpl.java&gt;, &lt;Request.java&gt;</span></span></code></pre></div><h3 id="cac-muc-bat-buoc" tabindex="-1">Các mục bắt buộc <a class="header-anchor" href="#cac-muc-bat-buoc" aria-label="Permalink to &quot;Các mục bắt buộc&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td><strong>Function Trigger</strong></td><td>Điều gì kích hoạt hàm (role nào + hành động trên route nào).</td></tr><tr><td><strong>Function Description</strong></td><td>Actors/Roles, Purpose (mục đích), Interface (màn hình), Data Processing (xử lý dữ liệu).</td></tr><tr><td><strong>Screen Layout</strong></td><td>Mô tả màn hình + <strong>chèn screenshot FE</strong> (sau khi code xong).</td></tr><tr><td><strong>Data Specifications</strong></td><td>Input required, System data, Output, Errors (mã + message).</td></tr><tr><td><strong>Business Rules</strong></td><td>Danh sách <code>BR-01</code>, <code>BR-02</code>, … (ràng buộc nghiệp vụ).</td></tr><tr><td><strong>Validation</strong></td><td>Từng field lỗi → hiển thị message gì.</td></tr><tr><td><strong>Normal Flow</strong></td><td>Các bước xử lý đúng chuẩn (đánh số).</td></tr><tr><td><strong>Abnormal Cases</strong></td><td>Case ngoại lệ + cách xử lý (lỗi, trùng, fail…).</td></tr><tr><td><strong>Post-Conditions</strong></td><td>Trạng thái dữ liệu sau khi hàm hoàn tất.</td></tr></tbody></table><hr><h2 id="_4-tai-lieu-tham-chieu" tabindex="-1">4. Tài liệu tham chiếu <a class="header-anchor" href="#_4-tai-lieu-tham-chieu" aria-label="Permalink to &quot;4. Tài liệu tham chiếu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nội dung</th><th>Đường dẫn</th></tr></thead><tbody><tr><td>Quy trình 4 file feature</td><td><code>brandhub-infrastructure/docs/rule/feature-workflow.md</code></td></tr><tr><td>Git commit convention</td><td><code>brandhub-infrastructure/docs/rule/git-commit-convention.md</code></td></tr><tr><td>Chuẩn code Backend</td><td><code>brandhub-business-service/rule.md</code></td></tr><tr><td>Chuẩn code Frontend</td><td><code>brandhub-web-dashboard/rule.md</code></td></tr><tr><td>Mẫu spec/plan/task/test</td><td><code>brandhub-infrastructure/docs/feature/system-maintenance/definition/</code></td></tr><tr><td>Đặc tả từng feature</td><td><code>brandhub-infrastructure/docs/feature/&lt;tên-feature&gt;/</code></td></tr><tr><td>Phân tích nghiệp vụ (BA)</td><td><code>brandhub-infrastructure/docs/ba/</code></td></tr><tr><td>Mẫu spec FR (Report 3)</td><td><code>FormReportDA/report_drafts/DA-763_R3_S3.2.1_FR_Register_Email.md</code></td></tr><tr><td>FR danh sách (Excel)</td><td><code>brandhub-infrastructure/docs/Các FR của hệ thống - Feature_Function Requirement.csv</code></td></tr><tr><td>Report 1–4</td><td><code>FormReportDA/reports/BrandHub_Report{1..4}_*.docx</code></td></tr><tr><td>BR/MSG chuẩn (dùng để cite trong spec)</td><td><code>FormReportDA/report_drafts/Section5_Requirement_Appendix.md</code></td></tr><tr><td>Migration DB (người đã có DB)</td><td><code>brandhub-infrastructure/docs/database/migrations/</code></td></tr><tr><td>Init DB (người tạo DB từ đầu)</td><td><code>brandhub-infrastructure/docs/database/init-postgres-v2.sql</code></td></tr></tbody></table><hr><h2 id="_5-tom-tat-nhanh" tabindex="-1">5. Tóm tắt nhanh <a class="header-anchor" href="#_5-tom-tat-nhanh" aria-label="Permalink to &quot;5. Tóm tắt nhanh&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pull develop (infra + business)</span></span>
<span class="line"><span>  → B1: check Jira, kéo In Progress</span></span>
<span class="line"><span>  → B2: Report 3 (spec FR) + Report 4 (Sequence diagram)</span></span>
<span class="line"><span>  → B3: đọc spec.md + BA, sửa nếu sai/thiếu</span></span>
<span class="line"><span>  → B4: viết plan.md + task.md + test.md (theo mẫu definition)</span></span>
<span class="line"><span>  → B5: code — BE (implement service impl + test) / FE (UI + responsive)</span></span>
<span class="line"><span>  → B6: commit đúng mã DA-xx</span></span>
<span class="line"><span>  → B7: In Review → Done + chụp FE chèn Report 3</span></span>
<span class="line"><span>  → B8: cập nhật cột &quot;Hiện trạng&quot; trên Excel</span></span></code></pre></div><hr><h2 id="_6-quy-đinh-migrate-database" tabindex="-1">6. Quy định migrate database <a class="header-anchor" href="#_6-quy-đinh-migrate-database" aria-label="Permalink to &quot;6. Quy định migrate database&quot;">​</a></h2><p>Schema PostgreSQL có <strong>2 điểm vào</strong> khác nhau, phục vụ 2 nhóm người khác nhau — phải cập nhật <strong>cả hai</strong> mỗi khi đổi schema, không được chỉ làm một:</p><table tabindex="0"><thead><tr><th>Điểm vào</th><th>Dùng cho ai</th><th>File</th></tr></thead><tbody><tr><td><strong>File migration riêng</strong></td><td>Người <strong>đã có DB chạy sẵn</strong> — chỉ cần chạy đúng migration mới, không phải tạo lại DB từ đầu.</td><td><code>brandhub-infrastructure/docs/database/migrations/&lt;YYYY-MM-DD&gt;-&lt;mô-tả&gt;.sql</code></td></tr><tr><td><strong><code>init-postgres-v2.sql</code></strong></td><td>Người <strong>tạo DB từ đầu</strong> (máy mới, CI, môi trường test) — file init phải luôn phản ánh đúng schema mới nhất, chạy 1 lần là ra DB đủ tất cả thay đổi tới thời điểm hiện tại.</td><td><code>brandhub-infrastructure/docs/database/init-postgres-v2.sql</code></td></tr></tbody></table><p><strong>Quy trình bắt buộc khi đổi schema (thêm/sửa/xoá cột, bảng, index, constraint):</strong></p><ol><li>Viết file migration mới trong <code>docs/database/migrations/</code>, đặt tên theo ngày + mô tả ngắn (xem các file hiện có làm mẫu), nội dung là SQL thuần chạy được trực tiếp (<code>ALTER TABLE ... ADD COLUMN IF NOT EXISTS ...</code>, <code>CREATE INDEX IF NOT EXISTS ...</code> — dùng <code>IF NOT EXISTS</code>/<code>IF EXISTS</code> để chạy lại không lỗi).</li><li>Áp <strong>đúng thay đổi đó</strong> vào <code>init-postgres-v2.sql</code> — không viết lại toàn bộ file, chỉ sửa đúng phần liên quan (thêm cột vào đúng <code>CREATE TABLE</code>, thêm index vào đúng chỗ) sao cho ai chạy <code>init-postgres-v2.sql</code> từ đầu sẽ ra kết quả <strong>giống hệt</strong> người chạy đủ migration.</li><li>Ghi migration đó vào task Jira / commit message để người khác biết cần pull + chạy.</li><li>Không xoá/sửa lại migration cũ đã merge — nếu sai, viết migration mới để sửa tiếp, tránh vỡ lịch sử của người đã chạy migration cũ trên DB thật.</li></ol><p><strong>Đối chiếu nhanh trước khi mở PR:</strong> file migration mới cộng dồn vào <code>init-postgres-v2.sql</code> đang có phải cho ra đúng schema hiện tại — nếu không chắc, có thể diff schema DB tạo bằng <code>init-postgres-v2.sql</code> với schema DB đã chạy đủ migration để xác nhận khớp nhau.</p>`,60)])])}const p=n(a,[["render",c]]);export{u as __pageData,p as default};
